clc; clearvars;
%%
root_dir = "..";
addpath(genpath(fullfile(root_dir, "\O3_Lidar\proc_functions")))
dataPath = fullfile(root_dir, "signal_analysis\data\20260427\");

data_format     = "bin"; %[control:dropdown:57a3]{"position":[19,24]}
prefix = "ol";

SNR_lim = 10;
n_shots = 1200;
tau = 1/(40e6);
dz = 3.75;
n_avg = 1;
fd = 270;

[an_R,pc_R,times,configs] = read_lidar_datafiles(dataPath,data_format,prefix);

n_bins = size(an_R,1);
n_prof = size(an_R,2);

h = (dz.*(1:n_bins))';
hkm = h./1000;

n_prof_avg = floor(n_prof / n_avg);

[an_bin,pc_P,times,an_B,pc_B] = preprocess(an_R,pc_R,times,dz,n_avg,n_shots,fd);
an_bin_bg = an_bin - an_B;
pc_P_bg = pc_P - pc_B;

an_bin_bg(an_bin_bg <= 0) = NaN;
pc_P_bg(pc_P_bg <= 0) = NaN;

an_mV_avg = scale_binary_analog(an_bin_bg,0,16,1201);
pc_p_avg = scale_binary_pc(pc_P_bg,3.75,1201);

etaQ_287 = 0.3;
etaQ_299 = 0.3;

mu_287 = 3e5;
mu_299 = 3e5;

%%
id = 21; %[control:slider:4211]{"position":[6,8]}
times.TimeZone = 'UTC';
% datetime(times(id),'TimeZone','America/New_York')
times(id) %[output:77ba2237]

an_287 = an_mV_avg(:,id,1);
an_299 = an_mV_avg(:,id,2);

pc_287 = pc_p_avg(:,id,1);
pc_299 = pc_p_avg(:,id,2);

Ik_287 = cathode_current(pc_287.*1e6,etaQ_287);
Ik_299 = cathode_current(pc_299.*1e6,etaQ_299);

Ip_287 = anode_current(Ik_287,mu_287);
Ip_299 = anode_current(Ik_299,mu_299);

bg_pc_287 = pc_B(1,id,1);
bg_pc_299 = pc_B(1,id,2);

N_287 = pc_287 .* 1e6 .* tau .* n_shots;
N_299 = pc_299 .* 1e6 .* tau .* n_shots;

NB_287 = bg_pc_287 .* 1e6 .* tau .* n_shots;
NB_299 = bg_pc_299 .* 1e6 .* tau .* n_shots;
%%
SNR_287_simple = sqrt(N_287);
SNR_287 = N_287 ./ sqrt(N_287 + NB_287);

SNR_299_simple = sqrt(N_299);
SNR_299 = N_299 ./ sqrt(N_299 + NB_299);
%%
dt = 1e6 * hkm.*1e3 * 2 / (3e8);

figure; %[output:09020dd1]
plot(dt,an_287,'DisplayName','287') %[output:09020dd1]
hold on %[output:09020dd1]
plot(dt,an_299,'DisplayName','299') %[output:09020dd1]
hold off %[output:09020dd1]
xlabel('Time (us)') %[output:09020dd1]
ylabel('Voltage (mV)') %[output:09020dd1]
grid on %[output:09020dd1]
legend %[output:09020dd1]
xlim([4 9]) %[output:09020dd1]
title('ADC Voltage') %[output:09020dd1]
figure; %[output:23ba035c]
semilogy(hkm,pc_287,'DisplayName','287') %[output:23ba035c]
hold on %[output:23ba035c]
plot(hkm,pc_299,'DisplayName','299') %[output:23ba035c]
hold off %[output:23ba035c]
xlabel('Alt (km)') %[output:23ba035c]
ylabel('Count Rate (MHz)') %[output:23ba035c]
grid on %[output:23ba035c]
legend %[output:23ba035c]
xlim([0 15]) %[output:23ba035c]
title('Count Rate') %[output:23ba035c]
figure; %[output:4610010b]
semilogy(hkm,Ip_287 .* 1e3,'DisplayName','287') %[output:4610010b]
hold on %[output:4610010b]
plot(hkm,Ip_299 .* 1e3,'DisplayName','299') %[output:4610010b]
hold off %[output:4610010b]
xlabel('Alt (km)') %[output:4610010b]
ylabel('Current (mA)') %[output:4610010b]
grid on %[output:4610010b]
legend %[output:4610010b]
xlim([0 15]) %[output:4610010b]
title('Anode Current') %[output:4610010b]
%%
figure; %[output:88e64dfa]
semilogy(hkm,SNR_287,'DisplayName','287') %[output:88e64dfa]
hold on %[output:88e64dfa]
plot(hkm,SNR_299,'DisplayName','299') %[output:88e64dfa]
yline(SNR_lim,'--') %[output:88e64dfa]
hold off %[output:88e64dfa]
xlabel('Alt (km)') %[output:88e64dfa]
ylabel('Count Rate (MHz)') %[output:88e64dfa]
grid on %[output:88e64dfa]
legend %[output:88e64dfa]
xlim([0 15]) %[output:88e64dfa]
title("Basic SNR 287 and 299 nm") %[output:88e64dfa]
figure %[output:42e531c3]
semilogy(hkm,SNR_287_simple,'DisplayName','without bg') %[output:42e531c3]
hold on %[output:42e531c3]
plot(hkm,SNR_287,'DisplayName','with bg') %[output:42e531c3]
grid on %[output:42e531c3]
legend %[output:42e531c3]
xlim([0 15]) %[output:42e531c3]
title("SNR 287 nm") %[output:42e531c3]
figure %[output:8a58b44c]
semilogy(hkm,SNR_299_simple,'DisplayName','without bg') %[output:8a58b44c]
hold on %[output:8a58b44c]
plot(hkm,SNR_299,'DisplayName','with bg') %[output:8a58b44c]
grid on %[output:8a58b44c]
legend %[output:8a58b44c]
xlim([0 15]) %[output:8a58b44c]
title("SNR 299 nm") %[output:8a58b44c]
%%
N = 50;
M = 2*N+1;
n = -N:N;
b = sgolay(1,M);
Cn = b((M+1)/2,:);

figure; %[output:65dfb0a1]
stem(n,b((M+1)/2,:)) %[output:65dfb0a1]
%%
% pc_287_filt = conv(pc(:,id,1),Cn,'same');
% pc_299_filt = conv(pc(:,id,2),Cn,'same');
% 
% SNR_287_filt = SNR_filt(N_287,NB_287,1,Cn);
% SNR_299_filt = SNR_filt(N_299,NB_299,1,Cn);
%%
% figure;
% semilogy(hkm,pc_287_filt,'DisplayName','287')
% hold on
% plot(hkm,pc_299_filt,'DisplayName','299')
% hold off
% xlabel('Alt (km)')
% ylabel('Count Rate (MHz)')
% grid on
% legend
% xlim([0 30])
% title('Count Rate Filtered')
% figure;
% semilogy(hkm,SNR_287_filt,'DisplayName','287')
% hold on
% plot(hkm,SNR_299_filt,'DisplayName','299')
% hold off
% xlabel('Alt (km)')
% ylabel('Count Rate (MHz)')
% grid on
% legend
% % xlim([0 30])
% title('SNR with filter')
% figure
% semilogy(hkm,SNR_299,'DisplayName','without filter')
% hold on
% plot(hkm,SNR_299_filt,'DisplayName','with filter')
% grid on
% legend
% xlim([0 15])
% title("SNR 299 nm")
%%
function Ik = cathode_current(r,etaQ)
    e = 1.60217663e-19;

    Ik = r .* e .* etaQ;
end

function Ip = anode_current(Ik,mu)
    Ip = Ik .* mu;
end

